import sys

MOD = 998244353

def power(base, exp):
    res = 1
    base %= MOD
    while exp > 0:
        if exp & 1:
            res = (res * base) % MOD
        base = (base * base) % MOD
        exp >>= 1
    return res

class Matrix:
    def __init__(self, mat):
        self.m = mat

    def pow(self, p):
        res = Matrix([[1, 0], [0, 1]])
        base = Matrix([row[:] for row in self.m])
        while p > 0:
            if p & 1:
                res = res.multiply(base)
            base = base.multiply(base)
            p >>= 1
        return res

    def multiply(self, m2):
        r = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    r[i][j] += self.m[i][k] * m2.m[k][j]
                r[i][j] %= MOD
        return Matrix(r)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    L = int(input_data[2])
    R = int(input_data[3])

    length = R - L + 1

    if n % 2 == 1 and m % 2 == 1:
        print(power(length % MOD, n * m))
    else:
        if length % 2 == 0:
            total = power(length % MOD, n * m - 1)
            answer = total * (length // 2) % MOD
            print(answer)
        else:
            half = length // 2
            identity = Matrix([[1, 0], [0, 1]])
            matrix = Matrix([[half, half + 1], [half + 1, half]])
            res = matrix.pow(n * m)
            print(res.m[0][0])

if __name__ == "__main__":
    main()

